home=f'''<section class="hero"><div class="wrap hero-grid"><div><h1>ECG, TENS &amp; Tab electrodes</h1><p>Taylor Industries is your premier source for monitoring ECG / EKG electrodes, TENS electrodes and Tab electrodes.</p><p>Our latex free, hypoallergenic electrodes are manufactured here in the United States in a wide variety of shapes, sizes and materials.</p><div class="actions">{button('/electrodes/','Electrodes')}{link('/production-machines/','Production machines','button button-outline')}</div></div>{img('brand/electrodes-collage.webp','A range of Taylor Industries electrodes','hero-image',True)}</div></section>{section('Electrodes','<p>We can also help develop and manufacture custom electrodes exclusive to your company.</p>'+cards())}<section class="section pale home-features"><div class="wrap split"><div><h2>ECG electrode features</h2><p>Disposable ECG / EKG electrodes manufactured in the United States.</p>{link('/electrodes/ecg/','Explore ECG electrodes <span aria-hidden="true">→</span>','text-link')}</div>{bullets(features)}</div></section><section class="section"><div class="wrap"><div class="section-heading"><div><h2>Production machines</h2><p>Bring production in-house with a custom-built electrode production machine from Taylor Industries. We can provide an easy-to-operate machine that is designed and built to address your specific needs.</p>{link('/production-machines/','View machines <span aria-hidden="true">→</span>','text-link')}</div></div><div class="home-machines"><a href="/production-machines/ecg-electrode-machine/" class="machine-photo">{img('machines/ECGMachine-Front1.jpg','ECG electrode production machine')}<span>ECG Electrode Production Machine →</span></a>{video()}</div></div></section><section class="contact-band"><div class="wrap band-inner"><h2>Contact Taylor Industries</h2><div class="band-contact"><a href="tel:+15738935412">573.893.5412</a><a href="mailto:sales@taylor-ind.com">sales@taylor-ind.com</a></div>{button('/contact/','Contact us')}</div></section>'''
pages={'/':('Electrodes & Production Machines',intro,home)}
