from urllib.parse import quote

def esc(v): return escape(str(v or ''), quote=True)
def anchor(p): return p['code']
def product_url(p): return '/electrodes/'+{'ECG':'ecg','TENS':'tens','Tab':'tab','Adhesive Strips':'adhesive-strips'}[p['category']]+'/#'+quote(anchor(p))
def size_in(p):
 return p["size_in"] + ((" " + p["shape"]) if p["category"] == "TENS" else ("" if '"' in p["size_in"] or not p["size_in"] else '"'))
def size_text(p):
 return size_in(p) + (f' ({p["size_mm"]})' if p["size_mm"] else "")
def mail(p):
 subject=f"Quote / sample request: {p['code']} {p['category']}"
 body=f"Product: {p['code']}\nSize: {size_text(p)}\nQuantity: \nCompany: "
 return 'mailto:sales@taylor-ind.com?subject='+quote(subject)+'&body='+quote(body)
def photo(p): return img(p['image'],p['code']+' '+(p['category']+' ' if p['category'] in ('ECG','TENS') else '')+'electrode','catalog-photo') if p['image'] else f'<div class="catalog-photo empty-photo">{esc(p["code"])}</div>'
def specs(p):
 fields=[('Size (in)',size_in(p)),('Size (mm)',p['size_mm']),('Material / element',p['material']),('Top laminate',p.get('laminate')),('Also available',p['available']),('Per card',p.get('card')),('Per pouch',p['pouch']),('Per box',p.get('box')),('Per case',p['case']),('Note',p['note'])]
 return ''.join(f'<dt>{esc(k)}</dt><dd>{esc(v)}{"*" if p["category"] == "ECG" and k in ("Per pouch", "Per case") else ""}</dd>' for k,v in fields if v) + ('<dt>Source</dt><dd>Listed in the Electrode Reference Guide</dd>' if p['source']=='guide' else '')
def product(p):
 sizeband = ('Up to 25 mm' if max(p['w'],p['h'])<=25 else '26–40 mm' if max(p['w'],p['h'])<=40 else '41–50 mm' if max(p['w'],p['h'])<=50 else 'Over 50 mm') if p['w'] else ''
 attrs={'code':p['code'],'alt':' '.join(p['alt']),'w':p['w'],'h':p['h'],'size':sizeband,'material':'Cloth version available' if p['alt'] and p['category']=='ECG' else '', 'outline':'Round' if 'diameter' in p['size_mm'] else '', 'pack':f"{p['pouch']} per pouch",'element':'Black Carbon' if p['material'].startswith('Black Carbon') else p['material'],'shape':p.get('shape',''),'available':p['available'],'pouch':p['pouch']}
 attrs=' '.join(f'data-{k}="{esc(v)}"' for k,v in attrs.items())
 size=esc(size_text(p))
 pack=' / '.join(f'{p[k]} per {k}' for k in ('card','pouch','box','case') if p.get(k))
 extra=(f'<p class="available">Also available in {esc(p["available"])}</p>' if p['available'] else '')+(f'<p>{esc(p["note"])}</p>' if p['note'] else '')
 wire=img('ecg/TL225_Disposable_ECG_Electrode_with_wire.jpg','TL225 electrode with lead wire','catalog-detail-photo') if p['code']=='TL225' else ''
 compare=f'<label class="compare-check" hidden><input type="checkbox" class="compare-input" aria-label="Compare {esc(p["code"])}"> Compare</label>' if p['category'] in ('ECG','TENS') else ''
 contact=f'<a class="contact-link" href="/contact/?product={quote(p["code"])}">Contact form</a>'
 material='' if p['category']=='ECG' else f'<p class="material">{esc(p["material"])}'+(f' / {esc(p["laminate"])}' if p.get('laminate') else '')+'</p>'
 return f'<article id="{esc(anchor(p))}" class="product" {attrs} data-size-text="{esc(size_text(p))}">{photo(p)}<div class="product-copy"><h3>{esc(p["code"])}</h3><p class="product-size">{size}</p>{material}<p class="product-pack">{pack}</p>{extra}</div><div class="product-actions"><a class="button quote" href="{mail(p)}" aria-label="Request quote / samples"><span class="quote-full">Request quote / samples</span><span class="quote-short">Quote / samples</span></a><div class="action-row">{compare}</div></div><details><summary>Details</summary><dl>{specs(p)}</dl>{wire}</details></article>'

def table(items):
 ecg=items[0]['category']=='ECG'
 rows=''.join(f'<tr data-code="{esc(p["code"])}"><th scope="row"><a href="#{esc(anchor(p))}">{esc(p["code"])}</a></th><td>{esc(size_in(p))}</td><td>{esc(p["size_mm"])}</td>{"" if ecg else "<td>"+esc(p["material"])+((" / "+esc(p["laminate"])) if p.get("laminate") else "")+"</td>"}<td>{esc(p["available"])}</td><td>{esc(p["pouch"])}</td><td>{esc(p["case"])}</td></tr>' for p in items)
 return '<details class="spec-details"><summary>Spec table</summary><span class="scroll-hint" hidden>Scroll →</span><div class="table-wrap" role="region" aria-label="Spec table" tabindex="0"><table><caption>Electrode specifications</caption><thead><tr>'+''.join('<th scope="col">'+x+'</th>' for x in ['Code','Size (in)','Size (mm)']+([] if ecg else ['Material/element'])+['Also available','Per pouch','Per case'])+'</tr></thead><tbody>'+rows+'</tbody></table></div></details>'
def toolbar(items,category):
 groups={'ECG':{'size':['Up to 25 mm','26–40 mm','41–50 mm','Over 50 mm'],'material':['Cloth version available'],'outline':['Round'],'pack':['30 per pouch','20 per pouch']},'TENS':{'element':['Tin','Black Carbon'],'shape':['Square','Rectangle','Round','Oval'],'available':['White Cloth','Foam'],'pouch':['4','2','1']}}[category]
 titles={'size':'Size','material':'Material','outline':'Outline','pack':'Pack','element':'Conductive element','shape':'Shape','available':'Also available in','pouch':'Per pouch'}
 fields=''
 for key,values in groups.items():
  chips=''
  for value in values:
   def match(p):
    if key=='size':
     n=max(p['w'],p['h']); return (n<=25 if value=='Up to 25 mm' else 26<=n<=40 if value=='26–40 mm' else 41<=n<=50 if value=='41–50 mm' else n>50)
    if key=='material': return bool(p['alt'])
    if key=='outline': return 'diameter' in p['size_mm']
    if key=='pack': return value==f"{p['pouch']} per pouch"
    if key=='element': return p['material'].startswith(value)
    if key=='available': return value in p['available']
    return str(p.get(key,''))==value
   count=sum(bool(match(p)) for p in items)
   if count: chips+=f'<label class="chip"><input type="checkbox" name="{key}" value="{esc(value)}"><span>{esc(value)} ({count})</span></label>'
  if chips: fields+=f'<fieldset><legend>{titles[key]}</legend>{chips}</fieldset>'
 return f'''<div class="catalog-toolbar" hidden><div class="toolbar-top"><div class="search-field"><label for="catalog-search">Search by product code</label><input id="catalog-search" type="search"></div><button type="button" class="filter-toggle" aria-expanded="false" aria-controls="filters">Filters (0)</button><div class="toolbar-controls"><span class="result-count" aria-live="polite"></span><label>Sort <select id="catalog-sort"><option value="default">Product code</option><option value="small">Size: small to large</option><option value="large">Size: large to small</option></select></label><div class="views"><button type="button" data-view="cards" aria-pressed="true">Cards</button><button type="button" data-view="table" aria-pressed="false">Table</button></div><button type="button" class="print-table">Print spec table</button><button type="button" class="clear" hidden>Clear</button></div></div><div id="filters" class="filters">{fields}</div></div>'''
def related(current): return '<nav class="catalog-related wrap" aria-label="Electrode categories"><span>More electrodes</span>'+ ''.join(link(u,n) for n,u,_ in categories if u!=current)+'</nav>'
