index_cards='<div class="category-grid">'+''.join(f'<a class="category-card" href="{u}"><div class="category-image">{img(p,n)}</div><span>{n}</span>'+ (f'<span class="category-count">{sum(x["category"]==cat for x in CATALOG)} products</span>' if cat else '')+'</a>' for (n,u,p),cat in zip(categories,['ECG','TENS','Tab','Adhesive Strips',None]))+'</div>'
pdf_size=(S/'assets/Electrode_Reference_Guide.pdf').stat().st_size/1000000
